use std::process::{Command, Stdio};

fn xdg_config_home() -> PathBuf {
    if let Ok(p) = env::var("XDG_CONFIG_HOME") {
        PathBuf::from(p)
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".config")
    }
}
fn xdg_data_home() -> PathBuf {
    if let Ok(p) = env::var("XDG_DATA_HOME") {
        PathBuf::from(p)
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::from(home).join(".local/share")
    }
}
fn xdg_data_dirs() -> Vec<PathBuf> {
    if let Ok(p) = env::var("XDG_DATA_DIRS") {
        if p.is_empty() {
            vec![PathBuf::from("/usr/local/share"), PathBuf::from("/usr/share")]
        } else {
            p.split(':').map(PathBuf::from).collect()
        }
    } else {
        vec![PathBuf::from("/usr/local/share"), PathBuf::from("/usr/share")]
    }
}

#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    path: PathBuf,
    filename: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name = None;
    let mut exec = None;
    let mut in_entry = false;
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            if line == "[Desktop Entry]" {
                in_entry = true;
            } else {
                if in_entry { break; }
            }
            continue;
        }
        if !in_entry { continue; }
        if let Some(idx) = line.find('=') {
            let key = &line[..idx];
            let val = &line[idx+1..];
            match key {
                "Name" => { if name.is_none() { name = Some(val.to_string()); } },
                "Exec" => { if exec.is_none() { exec = Some(val.to_string()); } },
                _ => {}
            }
        }
    }
    let name = name?;
    let exec = exec?;
    let filename = path.file_name()?.to_string_lossy().to_string();
    Some(DesktopEntry { name, exec, path: path.to_path_buf(), filename })
}

fn parse_mimeapps_desktop_mimetypes(path: &Path) -> Vec<String> {
    let content = match fs::read_to_string(path) { Ok(c) => c, Err(_) => return vec![] };
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" { in_entry = true; } else { if in_entry { break; } }
            continue;
        }
        if !in_entry { continue; }
        if let Some(idx) = t.find('=') {
            let key = &t[..idx];
            if key == "MimeType" {
                let val = &t[idx+1..];
                return val.split(';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
            }
        }
    }
    vec![]
}

fn ensure_config_dir() {
    let cfg_home = xdg_config_home();
    let handlr_dir = cfg_home.join("handlr");
    let _ = fs::create_dir_all(&handlr_dir);
    let toml_path = handlr_dir.join("handlr.toml");
    if !toml_path.exists() {
        let content = "enable_selector = false\nselector = \"rofi -dmenu -i -p 'Open With: '\"\n";
        let _ = fs::write(&toml_path, content);
        // also ensure mimeapps.list exists (empty) ? Observed: first run creates empty mimeapps.list
        let mime_path = cfg_home.join("mimeapps.list");
        if !mime_path.exists() {
            let _ = fs::write(&mime_path, "");
        }
    } else {
        // ensure mimeapps.list exists as empty if not
        let mime_path = cfg_home.join("mimeapps.list");
        if !mime_path.exists() {
            let _ = fs::write(&mime_path, "");
        }
    }
}

