#[derive(Debug)]
struct MimeApps {
    default: BTreeMap<String, Vec<String>>, // mime -> handlers list
    added: BTreeMap<String, Vec<String>>,
}
impl MimeApps {
    fn empty() -> Self { Self { default: BTreeMap::new(), added: BTreeMap::new() } }
}

fn parse_mimeapps_list(path: &Path) -> MimeApps {
    let content = match fs::read_to_string(path) { Ok(c) => c, Err(_) => return MimeApps::empty() };
    let mut default = BTreeMap::new();
    let mut added = BTreeMap::new();
    let mut current = None::<String>; // section name
    for raw_line in content.lines() {
        let line = raw_line.trim();
        if line.is_empty() { continue; }
        if line.starts_with('[') && line.ends_with(']') {
            let sec = line[1..line.len()-1].to_string();
            current = Some(sec);
            continue;
        }
        // key=value
        if let Some(idx) = line.find('=') {
            let mime = line[..idx].trim().to_string();
            let val = line[idx+1..].trim();
            // split by ';'
            let handlers: Vec<String> = val.split(';').filter(|s| !s.is_empty()).map(|s| s.trim().to_string()).collect();
            // Note: preserve order as in file for list? But for get we use first.
            // For parsing, we keep order.
            if let Some(sec) = &current {
                if sec == "Default Applications" {
                    default.insert(mime, handlers);
                } else if sec == "Added Associations" {
                    added.insert(mime, handlers);
                }
            }
        }
    }
    MimeApps { default, added }
}

