fn get_all_desktop_files() -> HashMap<String, DesktopEntry> {
    let mut map = HashMap::new();
    let mut seen_files: Vec<PathBuf> = vec![];
    let home = xdg_data_home();
    let mut search_paths = vec![home.join("applications")];
    for dir in xdg_data_dirs() {
        search_paths.push(dir.join("applications"));
    }
    for base in search_paths {
        if !base.is_dir() { continue; }
        if let Ok(entries) = fs::read_dir(&base) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|s| s.to_str()) != Some("desktop") { continue; }
                // For system apps order, we need to preserve filesystem reading order? The observed order was filesystem order (creation order) not sorted. However BTreeMap for display earlier showed default list sorted, but system apps list order of handlers per mime seems filesystem order? Let's check: earlier we created z,a,m and list showed z,a,m order. So system apps preserve read order. But our HashMap will deduplicate by filename, keeping first encountered? XDG spec: user data home takes precedence over system. So we should iterate in order: data_home first, then data_dirs in order. And if duplicate filename, first wins.
                let filename = match path.file_name().and_then(|s| s.to_str()) { Some(f) => f.to_string(), None => continue };
                if map.contains_key(&filename) { continue; }
                if let Some(de) = parse_desktop_file(&path) {
                    map.insert(filename, de);
                }
            }
        }
    }
    map
}

// Also need system mime associations: mime -> Vec<DesktopEntry> in order of discovery.
fn get_system_associations() -> BTreeMap<String, Vec<String>> {
    // Returns mime -> list of handler filenames (in discovery order)
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let home = xdg_data_home();
    let mut search_paths = vec![home.join("applications")];
    for dir in xdg_data_dirs() {
        search_paths.push(dir.join("applications"));
    }
    let mut seen = HashSet::new();
    for base in search_paths {
        if !base.is_dir() { continue; }
        if let Ok(entries) = fs::read_dir(&base) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|s| s.to_str()) != Some("desktop") { continue; }
                let filename = match path.file_name().and_then(|s| s.to_str()) { Some(f) => f.to_string(), None => continue };
                if seen.contains(&filename) { continue; }
                seen.insert(filename.clone());
                let mimes = parse_mimeapps_desktop_mimetypes(&path);
                for mime in mimes {
                    let entry = map.entry(mime).or_default();
                    // avoid duplicate handler in same mime list
                    if !entry.contains(&filename) {
                        entry.push(filename.clone());
                    }
                }
            }
        }
    }
    map
}

