#[derive(Debug, Clone)]
struct MimeApps {
    default: BTreeMap<String, Vec<String>>,
    added: BTreeMap<String, Vec<String>>,
}
impl MimeApps {
    fn empty() -> Self {
        Self { default: BTreeMap::new(), added: BTreeMap::new() }
    }
}

fn parse_mimeapps_file(path: &Path) -> MimeApps {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return MimeApps::empty(),
    };
    let mut default = BTreeMap::new();
    let mut added = BTreeMap::new();
    let mut cur: Option<String> = None;
    for raw in content.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            cur = Some(line[1..line.len()-1].to_string());
            continue;
        }
        if let Some(idx) = line.find('=') {
            let mime = line[..idx].trim().to_string();
            let val = line[idx+1..].trim();
            let handlers: Vec<String> = val.split(';').filter(|s| !s.is_empty()).map(|s| s.trim().to_string()).collect();
            match cur.as_deref() {
                Some("Default Applications") => { default.insert(mime, handlers); },
                Some("Added Associations") => { added.insert(mime, handlers); },
                _ => {}
            }
        }
    }
    MimeApps { default, added }
}

fn write_mimeapps_file(path: &Path, apps: &MimeApps) {
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let mut out = String::new();
    out.push_str("[Added Associations]\n");
    for (mime, handlers) in &apps.added {
        if !handlers.is_empty() {
            out.push_str(&format!("{}={};\n", mime, handlers.join(";")));
        }
    }
    out.push_str("\n");
    out.push_str("[Default Applications]\n");
    for (mime, handlers) in &apps.default {
        if !handlers.is_empty() {
            out.push_str(&format!("{}={};\n", mime, handlers.join(";")));
        }
    }
    let _ = fs::write(path, out);
}

fn get_all_desktop_entries() -> HashMap<String, DesktopEntry> {
    let mut map = HashMap::new();
    let mut seen = HashSet::new();
    let home = xdg_data_home();
    let mut search = vec![home.join("applications")];
    for d in xdg_data_dirs() {
        search.push(d.join("applications"));
    }
    for base in search {
        if !base.is_dir() { continue; }
        if let Ok(rd) = fs::read_dir(&base) {
            for ent in rd.flatten() {
                let p = ent.path();
                if p.extension().and_then(|s| s.to_str()) != Some("desktop") { continue; }
                let fname = match p.file_name().and_then(|s| s.to_str()) { Some(s) => s.to_string(), None => continue };
                if seen.contains(&fname) { continue; }
                seen.insert(fname.clone());
                if let Some(de) = parse_desktop_file(&p) {
                    map.insert(fname, de);
                }
            }
        }
    }
    map
}

