fn mime_parse_error(input: &str) -> Result<(String,String,bool,bool), String> {
    // Returns (type, subtype, has_params, is_wildcard_subtype)
    // Err string is the mime crate-like error message (without prefix)
    // Special case: starts with '.' -> "could not figure out the mime type of '{}'"
    if input.starts_with('.') {
        return Err(format!("could not figure out the mime type of '{}'", input));
    }
    // Check for empty?
    if input.is_empty() {
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    }
    // Split params by ';' first, but need to keep original for position reporting for type/subtype part?
    // We'll first isolate type_subtype part as up to first ';'
    let semi_pos = input.find(';');
    let type_subtype = if let Some(pos) = semi_pos { &input[..pos] } else { input };
    let has_params = semi_pos.is_some();

    // Check for invalid token characters in type_subtype before slash logic?
    // We need to find first invalid token position.
    // Allowed token chars: alphanumeric + "!#$%&'*+-.^_`|~"  (RFC token) . Actually '*' allowed, and also '-' '+' '.' etc.
    // We'll define allowed: A-Z a-z 0-9 ! # $ % & ' * + - . ^ _ ` | ~
    // Note: '*' is allowed, '/' is separator, not allowed in token.
    // For type_subtype, we expect one '/'. If we find char not in allowed and not '/', it's invalid.

    // Helper to check allowed token char
    fn is_token_char(c: char) -> bool {
        c.is_ascii_alphanumeric() || matches!(c, '!' | '#' | '$' | '%' | '&' | '\'' | '*' | '+' | '-' | '.' | '^' | '_' | '`' | '|' | '~')
    }

    // First, check for more than one '/'
    let slash_count = type_subtype.matches('/').count();
    if slash_count == 0 {
        // Check for invalid token in whole type_subtype
        for (i, ch) in type_subtype.char_indices() {
            if !is_token_char(ch) {
                // report invalid token at position i
                let hex = format!("{:02X}", ch as u8);
                return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
            }
        }
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    } else if slash_count > 1 {
        // find position of second slash
        let mut first = None;
        for (i, ch) in type_subtype.char_indices() {
            if ch == '/' {
                if first.is_none() {
                    first = Some(i);
                } else {
                    return Err(format!("mime parse error: an invalid token was encountered, 2F at position {}", i));
                }
            }
        }
        unreachable!();
    }
    // exactly one slash
    let slash_idx = type_subtype.find('/').unwrap();
    if slash_idx == 0 {
        // leading slash
        return Err(format!("mime parse error: an invalid token was encountered, 2F at position 0"));
    }
    let type_part = &type_subtype[..slash_idx];
    let subtype_part = &type_subtype[slash_idx+1..];
    // empty checks
    if type_part.is_empty() || subtype_part.is_empty() {
        // For subtype empty, bad mime; for type empty we already handled leading slash as invalid token.
        // But also check "a/" case: type "a", subtype "" -> bad mime
        return Err(format!("bad mime: {}", input));
    }
    // check type chars
    for (i, ch) in type_part.char_indices() {
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
        }
    }
    // check subtype chars
    for (i, ch) in subtype_part.char_indices() {
        // subtype offset in original string is slash_idx+1 + i
        let pos = slash_idx + 1 + i;
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, pos));
        }
    }
    // Now params parsing, if has_params
    if has_params {
        // params part is after first ';'
        let params_str = &input[semi_pos.unwrap()+1..];
        // If params_str is empty or only whitespace? Then it would be like "a/b;" -> param empty, should be error equals missing? Let's check observed: "a/b;c" gave equals missing. So we need to parse params.
        // Split params by ';'
        let params: Vec<&str> = input[semi_pos.unwrap()..].split(';').collect();
        // First element is ";..."? Actually we already split first is type_subtype, but we have remaining params. We'll iterate over params[1..]
        for param in params.iter().skip(1) {
            let p = param.trim();
            if p.is_empty() {
                continue;
            }
            if !p.contains('=') {
                return Err("mime parse error: an equals sign (=) was missing between a parameter and its value".to_string());
            }
            // Further validation not needed
        }
    }
    let t = type_part.to_ascii_lowercase();
    let s = subtype_part.to_ascii_lowercase();
    let is_wild = s == "*";
    Ok((t, s, has_params, is_wild))
}

fn normalize_mime_for_storage(mime_input: &str) -> Result<String, String> {
    // For set/add, we need to return normalized mime string like "type/subtype" lowercased, stripped params
    // Also need to handle wildcard like "text/*" should be stored as "text/*"
    // Use mime_parse_error but then strip params and lower case.
    match mime_parse_error(mime_input) {
        Ok((t, s, _, _)) => {
            Ok(format!("{}/{}", t, s))
        },
        Err(e) => Err(e),
    }
}

fn mime_matches(pattern: &str, query_type: &str, query_subtype: &str, query_has_params: bool) -> bool {
    // pattern is stored normalized mime (lowercased, no params) like "text/*" or "image/png"
    // query is parsed query type/subtype
    // Rules:
    // - If pattern == query (exact) -> match only if query_has_params == false (since exact with params fails)
    // Actually we will handle exact separately
    // For wildcard: pattern subtype == "*" and pattern type == query_type
    // Then match regardless of query_has_params
    if let Some(slash) = pattern.find('/') {
        let p_type = &pattern[..slash];
        let p_sub = &pattern[slash+1..];
        if p_sub == "*" && p_type == query_type {
            return true;
        }
    }
    false
}

fn get_mime_parts_for_query(q: &str) -> Result<(String,String,bool), String> {
    // returns (type, subtype, has_params)
    match mime_parse_error(q) {
        Ok((t,s,has,_)) => Ok((t,s,has)),
        Err(e) => Err(e),
    }
}

fn find_handler_for_mime(query_mime: &str, apps: &MimeApps, system_map: &BTreeMap<String, Vec<String>>, valid_handlers: &HashMap<String, DesktopEntry>) -> Option<String> {
    // Returns handler filename
    let (q_type, q_subtype, q_has_params) = match get_mime_parts_for_query(query_mime) {
        Ok(v) => v,
        Err(_) => return None, // parsing error handled elsewhere
    };
    let q_full = format!("{}/{}", q_type, q_subtype);

    // 1. default exact, only if no params
    if !q_has_params {
        if let Some(handlers) = apps.default.get(&q_full) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    // 2. default wildcard
    for (mime, handlers) in &apps.default {
        if mime_matches(mime, &q_type, &q_subtype, q_has_params) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    // 3. system exact, only if no params
    if !q_has_params {
        if let Some(handlers) = system_map.get(&q_full) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    // 4. system wildcard
    for (mime, handlers) in system_map {
        if mime_matches(mime, &q_type, &q_subtype, q_has_params) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    None
}

fn find_all_handlers_for_mime(query_mime: &str, apps: &MimeApps, system_map: &BTreeMap<String, Vec<String>>, valid: &HashMap<String, DesktopEntry>) -> Vec<String> {
    // For get with multiple handlers? Actually get returns only first, but for list we need all default handlers for that mime.
    // For find_handler we return first, but for selector we need all handlers for mime (default only?).
    // When selector enabled and multiple handlers for mime, we need to get all handlers for that mime from default.
    let (q_type, q_subtype, q_has_params) = match get_mime_parts_for_query(query_mime) {
        Ok(v) => v,
        Err(_) => return vec![],
    };
    let q_full = format!("{}/{}", q_type, q_subtype);
    // Try default exact
    if !q_has_params {
        if let Some(handlers) = apps.default.get(&q_full) {
            let valid_list: Vec<String> = handlers.iter().filter(|h| valid.contains_key(*h)).cloned().collect();
            if !valid_list.is_empty() {
                return valid_list;
            }
        }
    }
    // default wildcard
    for (mime, handlers) in &apps.default {
        if mime_matches(mime, &q_type, &q_subtype, q_has_params) {
            let valid_list: Vec<String> = handlers.iter().filter(|h| valid.contains_key(*h)).cloned().collect();
            if !valid_list.is_empty() {
                return valid_list;
            }
        }
    }
    // system exact
    if !q_has_params {
        if let Some(handlers) = system_map.get(&q_full) {
            let valid_list: Vec<String> = handlers.iter().filter(|h| valid.contains_key(*h)).cloned().collect();
            if !valid_list.is_empty() {
                return valid_list;
            }
        }
    }
    // system wildcard
    for (mime, handlers) in system_map {
        if mime_matches(mime, &q_type, &q_subtype, q_has_params) {
            let valid_list: Vec<String> = handlers.iter().filter(|h| valid.contains_key(*h)).cloned().collect();
            if !valid_list.is_empty() {
                return valid_list;
            }
        }
    }
    vec![]
}

fn print_table(rows: Vec<(String,String)>) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }
    let max1 = rows.iter().map(|(a,_)| a.len()).max().unwrap();
    let max2 = rows.iter().map(|(_,b)| b.len()).max().unwrap();
    let w1 = max1 + 2;
    let w2 = max2 + 2;
    println!("┌{}┬{}┐", "─".repeat(w1), "─".repeat(w2));
    for (a,b) in rows {
        println!("│ {:<w1$} │ {:<w2$} │", a, b, w1=max1, w2=max2);
    }
    println!("└{}┴{}┘", "─".repeat(w1), "─".repeat(w2));
}

fn exec_cmd_from_desktop(exec_str: &str) -> String {
    // Remove %u %U %f %F field codes (and %u etc with preceding optional space??)
