    // So replace %u, %U, %f, %F with empty string.
    let mut s = exec_str.to_string();
    for code in &["%u", "%U", "%f", "%F"] {
        s = s.replace(code, "");
    }
    // Then also need to handle stripping extra spaces? Observed "test " has trailing space (single). So after replacement, "test %u %U %f %F" becomes "test    " (4 spaces) but observed "test " single space? Actually earlier we had "test %u %U %f %F" -> cmd "test ". That suggests after replacement, multiple spaces collapsed? Let's see: original "test %u %U %f %F" has spaces between codes. Removing codes leaves "test    " (test + 4 spaces). But output "test " is "test" + single space. So they might collapse multiple spaces or trim? Let's examine: "test %u %U %f %F" -> after removing codes, we have "test    " (test plus 4 spaces). If we trim trailing spaces, we get "test". But observed "test " has trailing space. Hmm.
    // Let's check other: "feh %u" -> cmd "feh " (with trailing space). So they keep one trailing space.
    // For "test %u %U %f %F", if they keep trailing space, they'd have "test    " (4 spaces) but observed "test " (1 space). So they must be doing something like splitting exec by spaces and filtering out field codes that are standalone tokens? Or they remove field codes and then collapse multiple spaces into single space and trim? Let's test: "feh %u" -> tokens ["feh", "%u"] -> remove "%u" -> ["feh"] -> join with " " -> "feh" (no trailing space). But observed "feh " has trailing space. So not that.
    // Alternative: they take exec string, remove %u etc, but also preserve original spacing but after removal they maybe trim and then add single trailing space? Let's examine more examples.
    // We have earlier:
    // Exec "feh %u" -> cmd "feh " (feh + space). So they keep space before %u.
    // Exec "test %u %U %f %F" -> cmd "test " (test + space). That could be "test " if they remove codes but keep first space? Actually "test %u %U %f %F" has "test" + space + "%u" + space + "%U" + space + "%f" + space + "%F" . Removing codes leaves "test    " (test + 4 spaces). If they then replace multiple spaces with single space? "test    " -> "test " after collapsing? That would give "test " (test + space). That matches.
    // Let's test with "complex --flag %u %U %f %F %k %i %c %d %D %n %N %v %m %% %u after" -> cmd "complex --flag %k %i %c %d %D %n %N %v %m %% after"
    // Original: "complex --flag %u %U %f %F %k %i %c %d %D %n %N %v %m %% %u after"
    // After removing %u %U %f %F, we get "complex --flag     %k %i %c %d %D %n %N %v %m %%  after" (with multiple spaces). If we collapse multiple spaces into single space, we get "complex --flag %k %i %c %d %D %n %N %v %m %% after" which matches observed! Because they had single spaces between.
    // So cmd generation seems to: remove %u %U %f %F, then collapse multiple whitespaces into single space, but keep single trailing space? Let's see: after collapsing, "test %u %U %f %F" -> "test " (test + space) because original had trailing code %F without trailing space, after removal, string ends with space? Actually original ends with "%F", no trailing space. After removal, it ends with space (the space before %F). Collapsing would keep single trailing space? But then trim? The observed "test " has trailing space, so they keep trailing space.
    // So algorithm for cmd: take exec, remove %u %U %f %F substrings, then maybe split and join with single space preserving trailing space? Let's attempt: remove codes, then split on whitespace? No.
    // Better: implement as: exec string, replace %u etc with "", then trim and then add? Let's attempt to replicate exactly:
    // For "feh %u": remove "%u" -> "feh " (feh + space). That's "feh " (with trailing space). That matches.
    // For "test %u %U %f %F": remove each code: 
    //   "test %u %U %f %F"
    //   remove %u -> "test  %U %f %F" (test + two spaces + %U ...)
    //   remove %U -> "test   %f %F"
    //   remove %f -> "test    %F"
    //   remove %F -> "test     " (test + 5 spaces)
    // Then collapsing multiple spaces to single space gives "test " (test + space). That matches.
    // For complex case: after removal, we have "complex --flag     %k %i %c %d %D %n %N %v %m %%  after" (multiple spaces). Collapsing gives expected.
    // So steps: remove codes, then replace any sequence of 2+ spaces with single space, but keep at least one space where there were spaces? Actually collapsing will reduce 5 spaces to 1.
    // Then what about leading/trailing? For "test %u %U %f %F", after removal we have trailing spaces (5). Collapsing to 1 gives single trailing space. So "test " matches.
    // For "feh %u", after removal "feh " (one trailing space) collapsing keeps one.
    // For exec without field codes, e.g., "nocode --flag", no removal, no collapsing needed, cmd is same.

    // Also need to handle quoted exec: original had Exec="quoted exec" %u and cmd was "quoted exec " (without quotes). So quotes should be stripped? Observed: Exec "\"/tmp/log.sh\" %u" gave cmd "/tmp/log.sh " (without quotes). So we should strip double quotes around tokens? Actually Exec parsing per desktop spec allows quoted strings. For simplicity, we will remove double quotes.

    // Let's implement cmd extraction:
    // - Take exec string, remove %u %U %f %F
    // - Then split by whitespace? No, we need to preserve args like "--flag" etc, but also handle quoted.
    // For json cmd, they seem to keep the exec without field codes but with args, and with spaces collapsed to single space, and trimmed? But trailing space preserved for cases where field code was at end.

    // Actually spec for cmd in json: it shows cmd like "feh " (with trailing space). So they preserve trailing space.

    // So we can implement: after removing codes, we replace "\t" with space, then collapse consecutive spaces into single space.

    // Let's do that.

    let mut without = s.clone();
    for code in &["%u", "%U", "%f", "%F"] {
        without = without.replace(code, "");
    }
    // Also need to handle quoted: remove " characters
    without = without.replace('"', "");
    // Collapse spaces: iterate and build new string where multiple spaces become single space
    let mut collapsed = String::new();
    let mut prev_space = false;
    for ch in without.chars() {
        if ch.is_whitespace() {
            if !prev_space {
                collapsed.push(' ');
                prev_space = true;
            }
        } else {
            collapsed.push(ch);
            prev_space = false;
        }
    }
    // The collapsed may have leading space if original started with space? Keep? Probably trim start? But exec shouldn't start with space.
    // Keep as is, but don't trim trailing? Our collapsed will have trailing space if original ended with space after removal (since last char space and prev_space false -> push space). So trailing space preserved as single space.
    // However if original had no trailing space and we removed code at end, we will have trailing space from before code. That's desired.
    // If original had no field code, no trailing space, collapsed has no trailing space.

    collapsed
}

fn get_cmd_for_handler(entry: &DesktopEntry) -> String {
    exec_cmd_from_desktop(&entry.exec)
}

fn launch_handler(handler_filename: &str, args: &[String], valid: &HashMap<String, DesktopEntry>) -> Result<(), String> {
    let entry = match valid.get(handler_filename) {
        Some(e) => e,
        None => return Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})")),
    };
    let exec = &entry.exec;
    // Parse exec for launch: need to replace %u %U %f %F etc with args
    // Logic observed:
    // - If exec contains %U or %F (capital), then all args are passed as single command invocation with args appended (grouped).
    // - If exec contains %u or %f (lowercase), then it also groups? Earlier we saw launch with %u and multiple args still grouped ("/tmp/a /tmp/b" in one call). So for launch, both lower and upper group.
    // - But for open, %u / %f splits per file, %U / %F groups.
    // For launch, we should always group args together?
    // Let's check earlier launch tests:
    //   logu with %u, launch with two args -> log showed "/tmp/a.txt /tmp/b.txt" (grouped)
    //   So launch groups even for %u.
    // - If exec contains no field code, then launch still passes args? Observed with lognone (no code), launch with args "/tmp/a" gave log "/tmp/a" (args passed). And launch with no args gave no args.
    // So for launch, if exec has field codes %u %U %f %F, replace them with args joined by space, otherwise append args at end.

    let has_lower = exec.contains("%u") || exec.contains("%f");
    let has_upper = exec.contains("%U") || exec.contains("%F");
    let has_any = has_lower || has_upper || exec.contains("%u") || exec.contains("%f") || exec.contains("%U") || exec.contains("%F");

    // Build command line: we need to split exec into program and args, handling field codes.
    // Simplify: we will create a command string where we replace %U %F %u %f with placeholder for args.
    // If exec contains any of those, replace all occurrences with args joined.
    // Else, append args at end.

    let args_str = args.join(" ");

    let mut exec_replaced = exec.clone();
    // Replace quoted handling: remove quotes for program parsing but keep for replacement?
    // For simplicity, we will replace codes in exec string, then use shell-like splitting? We need to actually spawn process, not just log.

    // The original handlr uses std::process::Command with exec parsing: it takes exec string, removes field codes %i %c %k etc? Actually we saw launch keeps %k %i %c as literal args? No, earlier we saw launch with exec containing "%k %i %c %u" and arg "/tmp/file" gave log "--flag %k %i %c /tmp/file" -> so %k %i %c kept as literal? Wait we had exec "/tmp/log.sh --flag %k %i %c %u" and launch with "/tmp/file" gave log "--flag %k %i %c /tmp/file". So %k %i %c remained literal (not expanded). That's what we saw. So only %u %U %f %F are replaced with args, other codes stay.

    // So for launch, we replace %U %u %f %F with args_str.

    let mut replaced = exec.clone();
    for code in &["%U", "%F", "%u", "%f"] {
        replaced = replaced.replace(code, &args_str);
    }
    // Then we need to execute it. We should parse replaced into program and args, handling quoted strings.
    // Simple shell split: split by whitespace, but respect quotes? For our tests, exec was simple: "/tmp/log.sh %u" -> after replacement "/tmp/log.sh /tmp/a /tmp/b" -> split into ["/tmp/log.sh", "/tmp/a", "/tmp/b"].
    // For quoted exec like "\"/tmp/log.sh\" %u" -> after replacement "\"/tmp/log.sh\" /tmp/a" -> we need to strip quotes.

    // We'll implement simple split: iterate chars, handle double quotes.

    let mut parts: Vec<String> = vec![];
    let mut current = String::new();
    let mut in_quotes = false;
    let mut escape = false;
    for ch in replaced.chars() {
        if escape {
            current.push(ch);
            escape = false;
            continue;
        }
        if ch == '\\' {
            escape = true;
            continue;
        }
        if ch == '"' {
            in_quotes = !in_quotes;
            continue;
        }
        if ch.is_whitespace() && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else {
            current.push(ch);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }
    if parts.is_empty() {
        return Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"));
    }
    let prog = parts[0].clone();
    let prog_args = parts[1..].to_vec();

    // Now spawn
    let mut cmd = Command::new(prog);
    cmd.args(prog_args);
    // detach? but we wait?
    match cmd.status() {
        Ok(status) => {
            if status.success() {
                Ok(())
            } else {
                // still ok? original returns Io error only when file not found, not on non-zero exit
                Ok(())
            }
        },
        Err(_) => {
            Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"))
        }
    }
}

