fn xdg_config_home() -> PathBuf {
    if let Ok(p) = env::var("XDG_CONFIG_HOME") {
        if !p.is_empty() {
            return PathBuf::from(p);
        }
    }
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".config")
}
fn xdg_data_home() -> PathBuf {
    if let Ok(p) = env::var("XDG_DATA_HOME") {
        if !p.is_empty() {
            return PathBuf::from(p);
        }
    }
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".local/share")
}
fn xdg_data_dirs() -> Vec<PathBuf> {
    if let Ok(p) = env::var("XDG_DATA_DIRS") {
        if p.is_empty() {
            vec![PathBuf::from("/usr/local/share"), PathBuf::from("/usr/share")]
        } else {
            p.split(':').filter(|s| !s.is_empty()).map(PathBuf::from).collect()
        }
    } else {
        vec![PathBuf::from("/usr/local/share"), PathBuf::from("/usr/share")]
    }
}

#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    filename: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name: Option<String> = None;
    let mut exec: Option<String> = None;
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            let k = &t[..idx];
            let v = &t[idx+1..];
            if k == "Name" && name.is_none() {
                name = Some(v.to_string());
            } else if k == "Exec" && exec.is_none() {
                exec = Some(v.to_string());
            }
        }
    }
    Some(DesktopEntry {
        name: name?,
        exec: exec?,
        filename: path.file_name()?.to_string_lossy().to_string(),
    })
}

fn parse_desktop_mimetypes(path: &Path) -> Vec<String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return vec![],
    };
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            if &t[..idx] == "MimeType" {
                let v = &t[idx+1..];
                return v.split(';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
            }
        }
    }
    vec![]
}

#[derive(Debug)]
struct Config {
    enable_selector: bool,
    selector: String,
}

fn load_config() -> Config {
    let cfg_home = xdg_config_home();
    let handlr_dir = cfg_home.join("handlr");
    let _ = fs::create_dir_all(&handlr_dir);
    let toml_path = handlr_dir.join("handlr.toml");
    if !toml_path.exists() {
        let content = "enable_selector = false\nselector = \"rofi -dmenu -i -p 'Open With: '\"\n";
        let _ = fs::write(&toml_path, content);
        let mime_path = cfg_home.join("mimeapps.list");
        if !mime_path.exists() {
            let _ = fs::write(&mime_path, "");
        }
        return Config {
            enable_selector: false,
            selector: "rofi -dmenu -i -p 'Open With: '".to_string(),
        };
    }
    // ensure mimeapps.list exists
    let mime_path = cfg_home.join("mimeapps.list");
    if !mime_path.exists() {
        let _ = fs::write(&mime_path, "");
    }
    let content = fs::read_to_string(&toml_path).unwrap_or_default();
    // very small TOML parser that will panic on bad data like original
    let mut enable_selector = false;
    let mut selector = "rofi -dmenu -i -p 'Open With: '".to_string();
    let mut had_error = false;
    for line in content.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') {
            continue;
        }
        if !l.contains('=') {
            had_error = true;
            break;
        }
        let mut iter = l.splitn(2, '=');
        let k = iter.next().unwrap().trim();
        let v = iter.next().unwrap().trim();
        if k == "enable_selector" {
            if v == "true" {
                enable_selector = true;
            } else if v == "false" {
                enable_selector = false;
            } else {
                had_error = true;
                break;
            }
        } else if k == "selector" {
            if v.starts_with('"') && v.ends_with('"') && v.len() >= 2 {
                selector = v[1..v.len()-1].to_string();
            } else {
                had_error = true;
                break;
            }
        }
    }
    if had_error {
        panic!("called `Result::unwrap()` on an `Err` value: BadTomlData(Error {{ inner: ErrorInner {{ kind: Wanted {{ expected: \"an equals\", found: \"an identifier\" }}, line: Some(0), col: 8, at: Some(8), message: \"\", key: [] }} }})");
    }
    Config { enable_selector, selector }
}

