    // returns map and order of first appearance? Actually we need ordered list per mime in discovery order, and also we need overall mime order? For list display, system apps sorted by mime alphabetically, but handlers per mime preserve discovery order.
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
