    // However if original had no trailing space and we removed code at end, we will have trailing space from before code. That's desired.
    // If original had no field code, no trailing space, collapsed has no trailing space.

    collapsed
}

fn get_cmd_for_handler(entry: &DesktopEntry) -> String {
