#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    filename: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name: Option<String> = None;
    let mut exec: Option<String> = None;
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            let k = &t[..idx];
            let v = &t[idx+1..];
            if k == "Name" && name.is_none() {
                name = Some(v.to_string());
            } else if k == "Exec" && exec.is_none() {
                exec = Some(v.to_string());
            }
        }
    }
    Some(DesktopEntry {
        name: name?,
        exec: exec?,
        filename: path.file_name()?.to_string_lossy().to_string(),
    })
}

fn parse_desktop_mimetypes(path: &Path) -> Vec<String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return vec![],
    };
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            if &t[..idx] == "MimeType" {
                let v = &t[idx+1..];
                return v.split(';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
            }
        }
    }
    vec![]
}

#[derive(Debug)]
struct Config {
    enable_selector: bool,
    selector: String,
}

fn load_config() -> Config {
    let cfg_home = xdg_config_home();
    let handlr_dir = cfg_home.join("handlr");
    let _ = fs::create_dir_all(&handlr_dir);
    let toml_path = handlr_dir.join("handlr.toml");
    if !toml_path.exists() {
        let content = "enable_selector = false\nselector = \"rofi -dmenu -i -p 'Open With: '\"\n";
        let _ = fs::write(&toml_path, content);
        let mime_path = cfg_home.join("mimeapps.list");
        if !mime_path.exists() {
            let _ = fs::write(&mime_path, "");
        }
        return Config {
            enable_selector: false,
            selector: "rofi -dmenu -i -p 'Open With: '".to_string(),
        };
    }
    let mime_path = cfg_home.join("mimeapps.list");
    if !mime_path.exists() {
        let _ = fs::write(&mime_path, "");
    }
    let content = fs::read_to_string(&toml_path).unwrap_or_default();
    let mut enable_selector = false;
    let mut selector = "rofi -dmenu -i -p 'Open With: '".to_string();
    let mut had_error = false;
    for line in content.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') {
            continue;
        }
        if !l.contains('=') {
            had_error = true;
            break;
        }
        let mut iter = l.splitn(2, '=');
        let k = iter.next().unwrap().trim();
        let v = iter.next().unwrap().trim();
        if k == "enable_selector" {
            if v == "true" {
                enable_selector = true;
            } else if v == "false" {
                enable_selector = false;
            } else {
                had_error = true;
                break;
            }
        } else if k == "selector" {
            if v.starts_with('"') && v.ends_with('"') && v.len() >= 2 {
                selector = v[1..v.len()-1].to_string();
            } else {
                had_error = true;
                break;
            }
        }
    }
    if had_error {
        panic!("called `Result::unwrap()` on an `Err` value: BadTomlData(Error {{ inner: ErrorInner {{ kind: Wanted {{ expected: \"an equals\", found: \"an identifier\" }}, line: Some(0), col: 8, at: Some(8), message: \"\", key: [] }} }})");
    }
    Config { enable_selector, selector }
}

#[derive(Debug, Clone)]
struct MimeApps {
    default: BTreeMap<String, Vec<String>>,
    added: BTreeMap<String, Vec<String>>,
}
impl MimeApps {
    fn empty() -> Self {
        Self { default: BTreeMap::new(), added: BTreeMap::new() }
    }
}

fn parse_mimeapps_file(path: &Path) -> MimeApps {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return MimeApps::empty(),
    };
    let mut default = BTreeMap::new();
    let mut added = BTreeMap::new();
    let mut cur: Option<String> = None;
    for raw in content.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            cur = Some(line[1..line.len()-1].to_string());
            continue;
        }
        if let Some(idx) = line.find('=') {
            let mime = line[..idx].trim().to_string();
            let val = line[idx+1..].trim();
            let handlers: Vec<String> = val.split(';').filter(|s| !s.is_empty()).map(|s| s.trim().to_string()).collect();
            match cur.as_deref() {
                Some("Default Applications") => { default.insert(mime, handlers); },
                Some("Added Associations") => { added.insert(mime, handlers); },
                _ => {}
            }
        }
    }
    MimeApps { default, added }
}

fn write_mimeapps_file(path: &Path, apps: &MimeApps) {
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let mut out = String::new();
    out.push_str("[Added Associations]\n");
    for (mime, handlers) in &apps.added {
        if !handlers.is_empty() {
            out.push_str(&format!("{}={};\n", mime, handlers.join(";")));
        }
    }
    out.push_str("\n");
    out.push_str("[Default Applications]\n");
    for (mime, handlers) in &apps.default {
        if !handlers.is_empty() {
            out.push_str(&format!("{}={};\n", mime, handlers.join(";")));
        }
    }
    let _ = fs::write(path, out);
}

fn get_all_desktop_entries() -> HashMap<String, DesktopEntry> {
    let mut map = HashMap::new();
    let mut seen = HashSet::new();
    let home = xdg_data_home();
    let mut search = vec![home.join("applications")];
    for d in xdg_data_dirs() {
        search.push(d.join("applications"));
    }
    for base in search {
        if !base.is_dir() { continue; }
        if let Ok(rd) = fs::read_dir(&base) {
            for ent in rd.flatten() {
                let p = ent.path();
                if p.extension().and_then(|s| s.to_str()) != Some("desktop") { continue; }
                let fname = match p.file_name().and_then(|s| s.to_str()) { Some(s) => s.to_string(), None => continue };
                if seen.contains(&fname) { continue; }
                seen.insert(fname.clone());
                if let Some(de) = parse_desktop_file(&p) {
                    map.insert(fname, de);
                }
            }
        }
    }
    map
}

fn get_system_associations_ordered() -> BTreeMap<String, Vec<String>> {
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut seen = HashSet::new();
    let home = xdg_data_home();
    let mut search = vec![home.join("applications")];
    for d in xdg_data_dirs() {
        search.push(d.join("applications"));
    }
    for base in search {
        if !base.is_dir() { continue; }
        if let Ok(rd) = fs::read_dir(&base) {
            for ent in rd.flatten() {
                let p = ent.path();
                if p.extension().and_then(|s| s.to_str()) != Some("desktop") { continue; }
                let fname = match p.file_name().and_then(|s| s.to_str()) { Some(s) => s.to_string(), None => continue };
                if seen.contains(&fname) { continue; }
                seen.insert(fname.clone());
                let mimes = parse_desktop_mimetypes(&p);
                for mime in mimes {
                    let entry = map.entry(mime).or_default();
                    if !entry.contains(&fname) {
                        entry.push(fname.clone());
                    }
                }
            }
        }
    }
    map
}

fn filter_valid_handlers(apps: &mut MimeApps, valid: &HashSet<String>) {
    for (_, handlers) in apps.default.iter_mut() {
        handlers.retain(|h| valid.contains(h));
    }
    for (_, handlers) in apps.added.iter_mut() {
        handlers.retain(|h| valid.contains(h));
    }
    apps.default.retain(|_, v| !v.is_empty());
    apps.added.retain(|_, v| !v.is_empty());
}

fn mime_parse_error(input: &str) -> Result<(String,String,bool,bool), String> {
    if input.starts_with('.') {
        return Err(format!("could not figure out the mime type of '{}'", input));
    }
    if input.is_empty() {
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    }
    let semi_pos = input.find(';');
    let type_subtype = if let Some(pos) = semi_pos { &input[..pos] } else { input };
    let has_params = semi_pos.is_some();

    fn is_token_char(c: char) -> bool {
        c.is_ascii_alphanumeric() || matches!(c, '!' | '#' | '$' | '%' | '&' | '\'' | '*' | '+' | '-' | '.' | '^' | '_' | '`' | '|' | '~')
    }

    let slash_count = type_subtype.matches('/').count();
    if slash_count == 0 {
        for (i, ch) in type_subtype.char_indices() {
            if !is_token_char(ch) {
                let hex = format!("{:02X}", ch as u8);
                return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
            }
        }
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    } else if slash_count > 1 {
        let mut first = None;
        for (i, ch) in type_subtype.char_indices() {
            if ch == '/' {
                if first.is_none() {
                    first = Some(i);
                } else {
                    return Err(format!("mime parse error: an invalid token was encountered, 2F at position {}", i));
                }
            }
        }
        unreachable!();
    }
    let slash_idx = type_subtype.find('/').unwrap();
    if slash_idx == 0 {
        return Err(format!("mime parse error: an invalid token was encountered, 2F at position 0"));
    }
    let type_part = &type_subtype[..slash_idx];
    let subtype_part = &type_subtype[slash_idx+1..];
    if type_part.is_empty() || subtype_part.is_empty() {
        return Err(format!("bad mime: {}", input));
    }
    for (i, ch) in type_part.char_indices() {
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
        }
    }
    for (i, ch) in subtype_part.char_indices() {
        let pos = slash_idx + 1 + i;
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, pos));
        }
    }
    if has_params {
        let rest = &input[semi_pos.unwrap()..];
        let parts: Vec<&str> = rest.split(';').collect();
        for param in parts.iter().skip(1) {
            let p = param.trim();
            if p.is_empty() {
                continue;
            }
            if !p.contains('=') {
                return Err("mime parse error: an equals sign (=) was missing between a parameter and its value".to_string());
            }
        }
    }
    let t = type_part.to_ascii_lowercase();
    let s = subtype_part.to_ascii_lowercase();
    let is_wild = s == "*";
    Ok((t, s, has_params, is_wild))
}

fn normalize_mime_for_storage(mime_input: &str) -> Result<String, String> {
    match mime_parse_error(mime_input) {
        Ok((t, s, _, _)) => Ok(format!("{}/{}", t, s)),
        Err(e) => Err(e),
    }
}

fn mime_matches(pattern: &str, query_type: &str) -> bool {
    if let Some(slash) = pattern.find('/') {
        let p_type = &pattern[..slash];
        let p_sub = &pattern[slash+1..];
        if p_sub == "*" && p_type == query_type {
            return true;
        }
    }
    false
}

fn get_mime_parts_for_query(q: &str) -> Result<(String,String,bool), String> {
    match mime_parse_error(q) {
        Ok((t,s,has,_)) => Ok((t,s,has)),
        Err(e) => Err(e),
    }
}

fn find_handler_for_mime(query_mime: &str, apps: &MimeApps, system_map: &BTreeMap<String, Vec<String>>, valid_handlers: &HashMap<String, DesktopEntry>) -> Option<String> {
    let (q_type, q_subtype, q_has_params) = match get_mime_parts_for_query(query_mime) {
        Ok(v) => v,
        Err(_) => return None,
    };
    let q_full = format!("{}/{}", q_type, q_subtype);

    if !q_has_params {
        if let Some(handlers) = apps.default.get(&q_full) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    for (mime, handlers) in &apps.default {
        if mime_matches(mime, &q_type) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    if !q_has_params {
        if let Some(handlers) = system_map.get(&q_full) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    for (mime, handlers) in system_map {
        if mime_matches(mime, &q_type) {
            if let Some(first) = handlers.first() {
                if valid_handlers.contains_key(first) {
                    return Some(first.clone());
                }
            }
        }
    }
    None
}

fn find_all_handlers_for_mime(query_mime: &str, apps: &MimeApps, system_map: &BTreeMap<String, Vec<String>>, valid: &HashMap<String, DesktopEntry>) -> Vec<String> {
    let (q_type, q_subtype, q_has_params) = match get_mime_parts_for_query(query_mime) {
        Ok(v) => v,
