fn mime_parse_error(input: &str) -> Result<(String,String,bool,bool), String> {
    if input.starts_with('.') {
        return Err(format!("could not figure out the mime type of '{}'", input));
    }
    if input.is_empty() {
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    }
    let semi_pos = input.find(';');
    let type_subtype = if let Some(pos) = semi_pos { &input[..pos] } else { input };
    let has_params = semi_pos.is_some();

    fn is_token_char(c: char) -> bool {
        c.is_ascii_alphanumeric() || matches!(c, '!' | '#' | '$' | '%' | '&' | '\'' | '*' | '+' | '-' | '.' | '^' | '_' | '`' | '|' | '~')
    }

    let slash_count = type_subtype.matches('/').count();
    if slash_count == 0 {
        for (i, ch) in type_subtype.char_indices() {
            if !is_token_char(ch) {
                let hex = format!("{:02X}", ch as u8);
                return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
            }
        }
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    } else if slash_count > 1 {
        let mut first = None;
        for (i, ch) in type_subtype.char_indices() {
            if ch == '/' {
                if first.is_none() {
                    first = Some(i);
                } else {
                    return Err(format!("mime parse error: an invalid token was encountered, 2F at position {}", i));
                }
            }
        }
        unreachable!();
    }
    let slash_idx = type_subtype.find('/').unwrap();
    if slash_idx == 0 {
        return Err(format!("mime parse error: an invalid token was encountered, 2F at position 0"));
    }
    let type_part = &type_subtype[..slash_idx];
    let subtype_part = &type_subtype[slash_idx+1..];
    if type_part.is_empty() || subtype_part.is_empty() {
        return Err(format!("bad mime: {}", input));
    }
    for (i, ch) in type_part.char_indices() {
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, i));
        }
    }
    for (i, ch) in subtype_part.char_indices() {
        let pos = slash_idx + 1 + i;
        if !is_token_char(ch) {
            let hex = format!("{:02X}", ch as u8);
            return Err(format!("mime parse error: an invalid token was encountered, {} at position {}", hex, pos));
        }
    }
    if has_params {
        let rest = &input[semi_pos.unwrap()..];
        let parts: Vec<&str> = rest.split(';').collect();
        for param in parts.iter().skip(1) {
            let p = param.trim();
            if p.is_empty() {
                continue;
            }
            if !p.contains('=') {
                return Err("mime parse error: an equals sign (=) was missing between a parameter and its value".to_string());
            }
        }
    }
    let t = type_part.to_ascii_lowercase();
    let s = subtype_part.to_ascii_lowercase();
    let is_wild = s == "*";
    Ok((t, s, has_params, is_wild))
}

fn normalize_mime_for_storage(mime_input: &str) -> Result<String, String> {
    match mime_parse_error(mime_input) {
        Ok((t, s, _, _)) => Ok(format!("{}/{}", t, s)),
        Err(e) => Err(e),
    }
}

fn mime_matches(pattern: &str, query_type: &str) -> bool {
    if let Some(slash) = pattern.find('/') {
        let p_type = &pattern[..slash];
        let p_sub = &pattern[slash+1..];
        if p_sub == "*" && p_type == query_type {
            return true;
        }
    }
    false
}

fn get_mime_parts_for_query(q: &str) -> Result<(String,String,bool), String> {
    match mime_parse_error(q) {
        Ok((t,s,has,_)) => Ok((t,s,has)),
        Err(e) => Err(e),
    }
}

