fn print_table(rows: Vec<(String,String)>) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }
    let max1 = rows.iter().map(|(a,_)| a.len()).max().unwrap();
    let max2 = rows.iter().map(|(_,b)| b.len()).max().unwrap();
    let w1 = max1 + 2;
    let w2 = max2 + 2;
    println!("┌{}┬{}┐", "─".repeat(w1), "─".repeat(w2));
    for (a,b) in rows {
        println!("│ {:<w1$} │ {:<w2$} │", a, b, w1=max1, w2=max2);
    }
    println!("└{}┴{}┘", "─".repeat(w1), "─".repeat(w2));
}

fn exec_cmd_from_desktop(exec_str: &str) -> String {
    let mut s = exec_str.to_string();
    for code in &["%u", "%U", "%f", "%F"] {
        s = s.replace(code, "");
    }
    s = s.replace('"', "");
    let mut collapsed = String::new();
    let mut prev_space = false;
    for ch in s.chars() {
        if ch.is_whitespace() {
            if !prev_space {
                collapsed.push(' ');
                prev_space = true;
            }
        } else {
            collapsed.push(ch);
            prev_space = false;
        }
    }
    collapsed
}

fn get_cmd_for_handler(entry: &DesktopEntry) -> String {
    exec_cmd_from_desktop(&entry.exec)
}

fn launch_handler(handler_filename: &str, args: &[String], valid: &HashMap<String, DesktopEntry>) -> Result<(), String> {
    let entry = match valid.get(handler_filename) {
        Some(e) => e,
        None => return Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})")),
    };
    let exec = &entry.exec;
    let args_str = args.join(" ");
    let mut replaced = exec.clone();
    for code in &["%U", "%F", "%u", "%f"] {
        replaced = replaced.replace(code, &args_str);
    }
    let mut parts: Vec<String> = vec![];
    let mut current = String::new();
    let mut in_quotes = false;
    for ch in replaced.chars() {
        if ch == '"' {
            in_quotes = !in_quotes;
            continue;
        }
        if ch.is_whitespace() && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else {
            current.push(ch);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }
    if parts.is_empty() {
        return Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})"));
    }
    let prog = parts[0].clone();
    let prog_args = parts[1..].to_vec();
    let mut cmd = Command::new(prog);
    cmd.args(prog_args);
    match cmd.status() {
        Ok(_) => Ok(()),
        Err(_) => Err(format!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})")),
    }
}

fn normalize_url(u: String) -> String {
    // Add trailing slash if no path
    if let Some(idx) = u.find("://") {
        let after_scheme = &u[idx+3..];
        // Find first occurrence of '/' '?' '#'
        let slash = after_scheme.find('/');
        if slash.is_none() {
            // No slash, need to insert "/" before ? or # or at end
            let q = after_scheme.find('?');
            let h = after_scheme.find('#');
            let mut host_end = after_scheme.len();
            if let Some(qpos) = q {
                host_end = host_end.min(qpos);
            }
            if let Some(hpos) = h {
                host_end = host_end.min(hpos);
            }
            let host = &after_scheme[..host_end];
            let rest = &after_scheme[host_end..];
            return format!("{}://{}/{}", &u[..idx], host, rest.trim_start_matches('/'));
            // Actually we need to handle rest starting with ? or # : should be "/?" not "//"
            // The above with "/{}" would give "//" if rest starts with "/". But slash is None, so rest doesn't start with "/".
            // For rest "?query", we need "/?query"
            // So format as "{}{}/{}"? Let's do more precise.
        }
    }
    // More precise handling
    if let Some(idx) = u.find("://") {
        let scheme = &u[..idx];
        let rest = &u[idx+3..];
        if let Some(slash_pos) = rest.find('/') {
            // has path, keep as is
            return u;
        } else {
            // no slash, check for ? or #
            if let Some(qpos) = rest.find('?') {
                let host = &rest[..qpos];
                let query = &rest[qpos..];
                return format!("{}://{}/{}", scheme, host, query);
            } else if let Some(hpos) = rest.find('#') {
                let host = &rest[..hpos];
                let frag = &rest[hpos..];
                return format!("{}://{}/{}", scheme, host, frag);
            } else {
                // host only
                return format!("{}://{}/", scheme, rest);
            }
        }
    }
    u
}

