#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    filename: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name: Option<String> = None;
    let mut exec: Option<String> = None;
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            let k = &t[..idx];
            let v = &t[idx+1..];
            if k == "Name" && name.is_none() {
                name = Some(v.to_string());
            } else if k == "Exec" && exec.is_none() {
                exec = Some(v.to_string());
            }
        }
    }
    Some(DesktopEntry {
        name: name?,
        exec: exec?,
        filename: path.file_name()?.to_string_lossy().to_string(),
    })
}

fn parse_desktop_mimetypes(path: &Path) -> Vec<String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return vec![],
    };
    let mut in_entry = false;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            if t == "[Desktop Entry]" {
                in_entry = true;
            } else if in_entry {
                break;
            }
            continue;
        }
        if !in_entry {
            continue;
        }
        if let Some(idx) = t.find('=') {
            if &t[..idx] == "MimeType" {
                let v = &t[idx+1..];
                return v.split(';').filter(|s| !s.trim().is_empty()).map(|s| s.trim().to_string()).collect();
            }
        }
    }
    vec![]
}

#[derive(Debug)]
struct Config {
