            let all_handlers = find_all_handlers_for_mime(&mime_input, &mimeapps, &system_map, &valid_handlers);
            if all_handlers.is_empty() {
                eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                std::process::exit(1);
