        "open" => {
            let mut help = false;
            let mut version = false;
            let mut paths: Vec<String> = vec![];
            for a in args.iter().skip(2) {
                match a.as_str() {
                    "-h" | "--help" => help = true,
                    "-V" | "--version" => version = true,
