            if paths.is_empty() {
                eprintln!("error: The following required arguments were not provided:\n    <paths>...\n\nUSAGE:\n    executable open <paths>...\n\nFor more information try --help");
                std::process::exit(2);
            }

            let mut groups: BTreeMap<String, Vec<String>> = BTreeMap::new();
            let mut failed = false;
            for p in paths {
                let mime = if p.contains("://") {
                    if let Some(idx) = p.find("://") {
                        let scheme = &p[..idx];
                        format!("x-scheme-handler/{}", scheme)
                    } else {
                        "application/octet-stream".to_string()
                    }
                } else {
                    let path = Path::new(&p);
                    if path.is_dir() {
                        "inode/directory".to_string()
                    } else {
                        if !path.exists() {
                            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                            failed = true;
                            continue;
                        }
                        "application/x-zerosize".to_string()
                    }
                };
                let all_handlers = find_all_handlers_for_mime(&mime, &mimeapps, &system_map, &valid_handlers);
                if all_handlers.is_empty() {
                    eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                    failed = true;
                    continue;
                }
                let mut chosen = all_handlers[0].clone();
                if config.enable_selector && all_handlers.len() > 1 {
                    let mut names = vec![];
                    for h in &all_handlers {
                        if let Some(entry) = valid_handlers.get(h) {
                            names.push(entry.name.clone());
                        } else {
                            names.push(h.clone());
                        }
                    }
                    let input = names.join("\n");
                    let mut child = Command::new("sh").arg("-c").arg(&config.selector).stdin(Stdio::piped()).stdout(Stdio::piped()).spawn().expect("selector");
                    if let Some(stdin) = child.stdin.as_mut() {
                        let _ = stdin.write_all(input.as_bytes());
                    }
                    let out = child.wait_with_output().expect("selector");
                    let out_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
                    if out_str.is_empty() {
                        chosen = all_handlers[0].clone();
                    } else {
                        let mut found = None;
                        for h in &all_handlers {
                            if let Some(entry) = valid_handlers.get(h) {
                                if entry.name == out_str {
                                    found = Some(h.clone());
                                    break;
                                }
                            }
                        }
                        match found {
                            Some(f) => chosen = f,
                            None => panic!("called `Option::unwrap()` on a `None` value"),
                        }
                    }
                }
                // normalize URL for open: add trailing slash if needed
                let normalized_p = if p.contains("://") {
                    // apply url normalization: if no path, add "/"
                    if let Some(idx) = p.find("://") {
                        let scheme = &p[..idx];
                        let rest = &p[idx+3..];
                        if rest.find('/').is_none() {
                            // no slash
                            if let Some(qpos) = rest.find('?') {
                                let host = &rest[..qpos];
                                let query = &rest[qpos..];
                                format!("{}://{}/{}", scheme, host, query)
                            } else if let Some(hpos) = rest.find('#') {
                                let host = &rest[..hpos];
                                let frag = &rest[hpos..];
                                format!("{}://{}/{}", scheme, host, frag)
                            } else {
                                format!("{}://{}/", scheme, rest)
                            }
                        } else {
                            p.clone()
                        }
                    } else {
                        p.clone()
                    }
                } else {
                    p.clone()
                };
                groups.entry(chosen).or_default().push(normalized_p);
            }

            for (handler, ps) in groups {
                let entry = match valid_handlers.get(&handler) {
                    Some(e) => e.clone(),
                    None => {
                        eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                        failed = true;
                        continue;
                    }
                };
                let exec = &entry.exec;
                let has_upper = exec.contains("%U") || exec.contains("%F");
                if has_upper {
                    let args_str = ps.join(" ");
                    let mut replaced = exec.clone();
                    for code in &["%U", "%F", "%u", "%f"] {
                        replaced = replaced.replace(code, &args_str);
                    }
                    let mut parts: Vec<String> = vec![];
                    let mut current = String::new();
                    let mut in_quotes = false;
                    for ch in replaced.chars() {
                        if ch == '"' {
                            in_quotes = !in_quotes;
                            continue;
                        }
                        if ch.is_whitespace() && !in_quotes {
                            if !current.is_empty() {
                                parts.push(current.clone());
                                current.clear();
                            }
                        } else {
                            current.push(ch);
                        }
                    }
                    if !current.is_empty() {
                        parts.push(current);
                    }
                    if parts.is_empty() { continue; }
                    let prog = parts[0].clone();
                    let prog_args = parts[1..].to_vec();
                    let mut cmd = Command::new(prog);
                    cmd.args(prog_args);
                    match cmd.status() {
                        Ok(_) => {},
