                            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                            failed = true;
                        }
                    }
                } else {
                    for p in ps {
                        let mut replaced = exec.clone();
                        for code in &["%u", "%f", "%U", "%F"] {
                            replaced = replaced.replace(code, &p);
                        }
                        let has_any = exec.contains("%u") || exec.contains("%U") || exec.contains("%f") || exec.contains("%F");
                        if !has_any {
                            replaced = format!("{} {}", replaced, p);
                        }
                        let mut parts: Vec<String> = vec![];
                        let mut current = String::new();
                        let mut in_quotes = false;
                        for ch in replaced.chars() {
                            if ch == '"' {
                                in_quotes = !in_quotes;
                                continue;
                            }
                            if ch.is_whitespace() && !in_quotes {
                                if !current.is_empty() {
                                    parts.push(current.clone());
                                    current.clear();
                                }
                            } else {
                                current.push(ch);
                            }
                        }
                        if !current.is_empty() {
                            parts.push(current);
                        }
                        if parts.is_empty() { continue; }
                        let prog = parts[0].clone();
                        let prog_args = parts[1..].to_vec();
                        let mut cmd = Command::new(prog);
                        cmd.args(prog_args);
                        match cmd.status() {
                            Ok(_) => {},
                            Err(_) => {
                                eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                                failed = true;
                            }
                        }
                    }
                }
            }
            if failed {
                std::process::exit(1);
            }
        },
        _ => {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable <SUBCOMMAND>\n\nFor more information try --help", sub);
            std::process::exit(2);
        }
    }
}
